import type { ImageSourcePropType } from 'react-native';

/**
 * Locally bundled deity artwork (works offline once the app is installed).
 *
 * Only artwork you have permission to use in the app should be added (your own,
 * commissioned, or generated by a tool whose terms allow commercial use). Until an
 * entry exists, the app shows the deity's colour emblem (src/content/emblemArt.ts).
 *
 * To add an image:
 *   1. Put a portrait image (3:4, about 1200 x 1600 px) in assets/deities/,
 *      e.g. assets/deities/shiva.png. Colour illustrations use kind: 'illustration'.
 *   2. Add an entry below with a static require() and the credit/licence.
 *   3. Run `npm run validate:content` to check the ids match deity profiles.
 *
 * Keys are deity ids from devotional_collection.json (`deities[].id`).
 */
export interface DeityArtwork {
  source: ImageSourcePropType;
  /** Shown on the deity page, e.g. "Photograph © Name, used with permission". */
  credit: string;
  /** Short licence or permission note, kept for your records and shown with the credit. */
  licence: string;
  /** Vertical focus for cropping, 0 (top) to 1 (bottom). Faces usually sit around 0.3. */
  focusY?: number;
  /**
   * 'illustration' (colour artwork, shown as drawn) or 'photo' (default: shown in grayscale
   * under a darker scrim, matching the app's monochrome look).
   */
  kind?: 'photo' | 'illustration';
}

/** Artwork supplied by the app owner (assets/god image), converted to 1024 px JPEGs. */
const OWNER = { credit: 'Artwork supplied by the Mandirpedia team', licence: 'Owner-supplied artwork, 2026', kind: 'illustration' as const };

export const deityArtwork: Partial<Record<string, DeityArtwork>> = {
  ganesha: { source: require('../../assets/deities/ganesha.jpg'), ...OWNER, focusY: 0.25 },
  hanuman: { source: require('../../assets/deities/hanuman.jpg'), ...OWNER, focusY: 0.25 },
  shiva: { source: require('../../assets/deities/shiva.jpg'), ...OWNER, focusY: 0.3 },
  vishnu: { source: require('../../assets/deities/vishnu.jpg'), ...OWNER, focusY: 0.25 },
  durga: { source: require('../../assets/deities/durga.jpg'), ...OWNER, focusY: 0.25 },
  lakshmi: { source: require('../../assets/deities/lakshmi.jpg'), ...OWNER, focusY: 0.25 },
  saraswati: { source: require('../../assets/deities/saraswati.jpg'), ...OWNER, focusY: 0.25 },
  krishna: { source: require('../../assets/deities/krishna.jpg'), ...OWNER, focusY: 0.25 },
  rama: { source: require('../../assets/deities/rama.jpg'), ...OWNER, focusY: 0.4 },
  kali: { source: require('../../assets/deities/kali.jpg'), ...OWNER, focusY: 0.25 },
  bhairava: { source: require('../../assets/deities/bhairava.jpg'), ...OWNER, focusY: 0.25 },
  narasimha: { source: require('../../assets/deities/narasimha.jpg'), ...OWNER, focusY: 0.3 },
  surya: { source: require('../../assets/deities/surya.jpg'), ...OWNER, focusY: 0.25 },
  tulsi: { source: require('../../assets/deities/tulsi.jpg'), ...OWNER, focusY: 0.25 },
  shitala: { source: require('../../assets/deities/shitala.jpg'), ...OWNER, focusY: 0.25 },
};

/** Ids of deities whose artwork is bundled. Used by the validator script. */
export const deityArtworkIds = (): string[] => Object.keys(deityArtwork).filter((k) => !!deityArtwork[k]);
